import * as THREE from './three.module.js';
import {CREATURES,ENCOUNTER_POSITIONS,REGION_BY_ID} from './rpg-data.js';
import {creatureModel,animateCreature} from './rpg-models.js';
import {CHAPTERS} from './adventure-data.js';
const boxGeo=new THREE.BoxGeometry(),mats=new Map();function mat(c,e=0){const k=c+':'+e;if(!mats.has(k))mats.set(k,new THREE.MeshStandardMaterial({color:c,roughness:.8,emissive:c,emissiveIntensity:e}));return mats.get(k)}
export function createRpgWorld({scene,store}){const cache=new Map();let adventure=null;const lastPlayer=new THREE.Vector3();let movement=0,lastTime=0;
 function build(id){if(cache.has(id))return cache.get(id);const r=REGION_BY_ID[id];if(!r||r.hub)return null;const root=new THREE.Group();root.position.set(r.x,0,r.z);scene.add(root);const obstacles=[],npcs=[];let seed=41+REGION_BY_ID[id].x**2+REGION_BY_ID[id].z**2;const random=()=>((seed=seed*16807%2147483647)-1)/2147483646;
 const B=(x,y,z,w,h,d,c=r.color,e=0)=>{const m=new THREE.Mesh(boxGeo,mat(c,e));m.position.set(x,y,z);m.scale.set(w,h,d);m.castShadow=true;m.receiveShadow=true;root.add(m);return m};
 const M=(geometry,x,y,z,c=r.color,e=0)=>{const m=new THREE.Mesh(geometry,mat(c,e));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;root.add(m);return m};
 const sign=(text,x,y,z,width=9)=>{const c=document.createElement('canvas');c.width=768;c.height=100;const ctx=c.getContext('2d');ctx.fillStyle='#183946';ctx.beginPath();ctx.roundRect(4,4,760,92,18);ctx.fill();ctx.fillStyle='#f3dfaa';ctx.font='600 35px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,384,53,730);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;const s=new THREE.Sprite(new THREE.SpriteMaterial({map:tex}));s.position.set(x,y,z);s.scale.set(width,width/7.68,1);root.add(s);return s};
 B(0,-3,0,65,6,57,0x8c9480);B(0,-.65,0,68,1.5,60,0xc8b892);B(0,.12,0,64,.34,55,r.color);B(0,.33,2,6,.1,46,0xe1d2ad);B(0,.34,0,49,.1,4,0xe1d2ad);B(0,.37,-2,14,.1,12,0xd7ccb0);B(0,.34,24,18,.12,5,0x526b72);for(let j=0;j<6;j++)B(-7+j*2.8,.42,24,1.2,.02,.2,0xffeac0);sign(r.name,0,4,19,10);sign('U-SPEAK AIR',0,2.4,24,6);
 for(let i=0;i<34;i++){const a=i/34*Math.PI*2,x=Math.cos(a)*32,z=Math.sin(a)*28;B(x,-1.3-random(),z,1.5+random()*3,1.5+random()*2,1.5+random()*3,i%2?0x9c9c87:0xb5ab8e)}
 // Central biome landmarks; the same navigable footprint keeps encounters accessible.
 const crystal=(x,z,h,c=r.accent)=>{M(new THREE.ConeGeometry(.8,h,5),x,h/2+.3,z,c,.12);M(new THREE.ConeGeometry(.5,h*.6,5),x+.9,h*.3+.2,z+.4,c,.08)};
 if(['grass','forest','moon'].includes(r.biome)){B(0,3.5,-6,2,7,2,0x6a6954);for(let i=0;i<5;i++){const a=i*1.26;const m=M(new THREE.SphereGeometry(3,10,7),Math.cos(a)*1.8,7+i*.4,-6+Math.sin(a)*1.8,r.biome==='moon'?0xb596c6:r.accent,.08);m.scale.y=.7}obstacles.push({x:0,z:-6,w:1.4,d:1.4})}
 if(['canyon','desert'].includes(r.biome)){for(let i=0;i<5;i++)B(0,.8+i*.75,-6,9-i*1.3,.85,7-i*.9,i%2?r.color:r.accent);obstacles.push({x:0,z:-6,w:4.6,d:3.6});for(const x of[-5.7,5.7])B(x,3,-7,1.2,6,1.2,r.accent)}
 if(['reef','snow'].includes(r.biome)){for(let j=0;j<5;j++){const a=j/5*Math.PI*2;crystal(Math.cos(a)*3,-6+Math.sin(a)*2,3+j*.8);obstacles.push({x:Math.cos(a)*3,z:-6+Math.sin(a)*2,w:.8,d:.8})}}
 if(['storm','ruins','sky'].includes(r.biome)){for(const x of[-4,4])for(const z of[-9,-3]){B(x,3,z,1.1,6,1.1,r.accent);B(x,6.3,z,1.5,.5,1.5,0xe0d6bb);obstacles.push({x,z,w:.8,d:.8})}B(0,6.7,-6,10,.6,9,r.color);const ring=M(new THREE.TorusGeometry(2.3,.14,8,64),0,3.5,-6,r.accent,.4);ring.rotation.y=.1;M(new THREE.OctahedronGeometry(.65),0,3.5,-6,r.accent,.5)}
 for(let i=0;i<38;i++){let x=(random()-.5)*57,z=(random()-.5)*47;if(Math.abs(x+11)<5&&Math.abs(z-8.5)<5||Math.abs(x)<5||Math.abs(z)<3||Math.hypot(x,z+6)<8||ENCOUNTER_POSITIONS.some(p=>Math.hypot(x-p.x,z-p.z)<3.5))continue;if(['reef','snow','storm','ruins'].includes(r.biome)){crystal(x,z,1+random()*3)}else if(r.biome==='desert'){B(x,1.3,z,.5,2.6,.5,0x7f9e76);B(x+.5,1.5,z,.7,.4,.4,0x7f9e76)}else if(r.biome==='moon'){B(x,1,z,.18,2,.18,0xd9c8d9);const sh=M(new THREE.SphereGeometry(1.2,10,6),x,2,z,i%2?r.color:r.accent,.12);sh.scale.y=.38}else{B(x,1.5,z,.3,3,.3,0x887454);B(x,3,z,2.1,1.7,2.1,r.accent);B(x,4,z,1.5,.6,1.5,r.color)}}
 for(let i=0;i<100;i++){const x=(random()-.5)*59,z=(random()-.5)*50;if(Math.abs(x+11)<5&&Math.abs(z-8.5)<5||Math.abs(x)<4||Math.abs(z)<3)continue;B(x,.45,z,.05,.48,.05,0x637d63);M(new THREE.OctahedronGeometry(.13),x,.76,z,i%2?r.accent:0xe4cbad,r.biome==='moon'?.3:0)}
 for(const c of CREATURES.filter(c=>c.region===id)){const p=ENCOUNTER_POSITIONS[c.slot],g=creatureModel(c);g.position.set(p.x,.22,p.z);root.add(g);const l=sign(c.name,p.x,3.3,p.z,4.2);l.visible=false;const marker=M(new THREE.OctahedronGeometry(.15),p.x,2.7,p.z,r.accent,.5);npcs.push({c,g,label:l,marker,x:p.x,z:p.z})}
 const npc=new THREE.Group();npc.position.set(-5,.25,7);root.add(npc);const piece=(geo,x,y,z,c)=>{const m=new THREE.Mesh(geo,mat(c));m.position.set(x,y,z);m.castShadow=true;npc.add(m);return m};piece(new THREE.CapsuleGeometry(.36,.55,3,8),0,.9,0,0x345b73);piece(new THREE.SphereGeometry(.34,12,10),0,1.64,0,0xe6ba8f);piece(new THREE.SphereGeometry(.36,12,8),0,1.79,-.04,0x554330);for(const side of[-1,1]){piece(new THREE.BoxGeometry(.24,.62,.28),side*.21,.31,0,0x36444d);piece(new THREE.BoxGeometry(.2,.7,.23),side*.49,.85,0,0x345b73);piece(new THREE.SphereGeometry(.033,6,5),side*.13,1.65,.32,0x243444)}piece(new THREE.BoxGeometry(.22,.08,.44),.51,.53,.18,r.accent);sign(CHAPTERS[id].npc+' · 地域の語り手',-5,3,7,6);obstacles.push({x:-5,z:7,w:.6,d:.5});
 const data={root,r,obstacles,npcs,npc};cache.set(id,data);return data;
 }
 function update(t,player,current,flightTarget,dt=.016){lastTime=t;const caught=new Set(store.state.caught);movement=player.position.distanceTo(lastPlayer)/Math.max(.001,dt);lastPlayer.copy(player.position);for(const [id,d]of cache){d.root.visible=id===current||id===flightTarget;if(!d.root.visible)continue;for(const n of d.npcs){const dist=Math.hypot(player.position.x-d.r.x-n.g.position.x,player.position.z-d.r.z-n.g.position.z);n.active=(!adventure||adventure.available(n.c))&&!(n.fledUntil>t);if(n.c.slot>=7&&dist<4&&movement>6.7&&movement<15&&!adventure?.sneaking()){n.fledUntil=t+8;n.active=false}n.g.visible=n.active;n.label.visible=n.active&&dist<9;n.marker.visible=n.active&&!caught.has(n.c.id);if(!n.active)continue;n.g.position.x=n.x+Math.sin(t*.28+n.c.number)*.65;n.g.position.z=n.z+Math.cos(t*.22+n.c.number)*.5;n.g.position.y=.22+(n.c.archetype==='manta'?.65:0)+Math.sin(t*1.2+n.c.number)*.07;animateCreature(n.g,t,n.c.number,dist<5?'happy':'idle');n.label.position.set(n.g.position.x,3.3,n.g.position.z);n.marker.position.set(n.g.position.x,2.7+Math.sin(t*2+n.c.number)*.13,n.g.position.z);n.marker.rotation.y=t;if(dist<9)adventure?.onSee(n.c.id);if(dist<8)n.g.rotation.y=Math.atan2(player.position.x-d.r.x-n.g.position.x,player.position.z-d.r.z-n.g.position.z);else n.g.rotation.y=Math.sin(t*.28+n.c.number)*.65}}}
 function nearby(current,player){const d=cache.get(current);if(!d)return null;return d.npcs.filter(n=>n.active!==false).map(n=>({n,dist:Math.hypot(player.position.x-d.r.x-n.g.position.x,player.position.z-d.r.z-n.g.position.z)})).filter(v=>v.dist<4.5).sort((a,b)=>a.dist-b.dist)[0]?.n.c||null}
 function blocked(id,x,z){const d=cache.get(id);if(!d)return null;const lx=x-d.r.x,lz=z-d.r.z;if(Math.abs(lx)>31||Math.abs(lz)>26.5)return true;return d.obstacles.some(o=>Math.abs(lx-o.x)<o.w+.3&&Math.abs(lz-o.z)<o.d+.3)}
 return {build,update,nearby,blocked,cache,setAdventure:a=>{adventure=a},flee:id=>{for(const d of cache.values()){const n=d.npcs.find(x=>x.c.id===id);if(n){n.fledUntil=lastTime+8;n.active=false}}}};
}
